// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Ensure caller is not address(0) to avoid OwnableInvalidOwner
        vm.assume(caller != address(0));
        // Simulate ownership transfer: owner renounces, then caller accepts
        vm.prank(c.owner());
        c.transferOwnership(caller);
        vm.prank(caller);
        c.acceptOwnership();
        // The proxiableUUID should be the standard ERC1967 implementation slot
        assertTrue(c.proxiableUUID() == 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc);
    }
}

